from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "clientes.html"
GUARD = ROOT / "homeeasy-page-guard.js"
OUTPUT = ROOT / "clientes-conectado-v31.html"

source = SOURCE.read_text(encoding="utf-8")
guard = GUARD.read_text(encoding="utf-8")

required_source_markers = [
    "#pantalla-inicio", "#pantalla-resultados", "function abrirVisorPDF", "function cerrarVisorPDF",
    "function abrirModalEditar", "function guardarEdicionCliente", "function confirmarEdicion",
    "function confirmarAnulacion", "function analizarAnulacion", "function ejecutarAnulacionSegura",
    "ANALIZAR_ANULACION_DOCUMENTO", "EJECUTAR_ANULACION_SEGURA", "HISTORIAL_CLIENTE",
    "listaClientes=1", "pedido.html?cotizacion=",
]
missing = [m for m in required_source_markers if m not in source]
if missing:
    raise SystemExit("clientes.html perdió funciones heredadas: " + ", ".join(missing))
if "'clientes.html': 'clientes.read'" not in guard:
    raise SystemExit("No se encontró el permiso clientes.read en el guard")

source = source.replace(
    'content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover"',
    'content="width=device-width, initial-scale=1.0, viewport-fit=cover"', 1)

guard = guard.replace("'clientes.html': 'clientes.read',",
    "'clientes.html': 'clientes.read',\n        'clientes-conectado-v31.html': 'clientes.read',", 1)
external_guard = '<script src="homeeasy-page-guard.js?v=3.6"></script>'
if external_guard not in source:
    raise SystemExit("No se encontró la referencia al guard 3.6")
source = source.replace(external_guard, '<script id="clientes-v31-inline-guard">\n' + guard + '\n</script>', 1)
source = source.replace("window.history.replaceState({}, '', `clientes.html?search=${cedula}`);",
    "window.history.replaceState({}, '', window.location.pathname + '?search=' + encodeURIComponent(cedula));")
source = source.replace("window.history.replaceState({}, '', 'clientes.html');",
    "window.history.replaceState({}, '', window.location.pathname);")
source = source.replace(
    "const drop = document.getElementById(id);\n            drop.style.display = drop.style.display === 'flex' ? 'none' : 'flex';",
    "const drop = document.getElementById(id);\n            if (!drop) return;\n            drop.style.display = drop.style.display === 'flex' ? 'none' : 'flex';", 1)
source = source.replace('<body>', '<body class="clientes-connected-v31">', 1)
preview_root = '\n        <div id="clientes-v31-connected" aria-live="polite"></div>\n'
marker = '        <div class="container">'
if marker not in source:
    raise SystemExit("No se encontró el contenedor legado de resultados")
source = source.replace(marker, preview_root + marker, 1)

