insert_at = source.rfind("</head>")
if insert_at < 0: raise SystemExit("No se encontró </head>")
source = source[:insert_at] + CSS + "\n" + JS + "\n" + source[insert_at:]
required_output_markers = ["Historial de abonos", "Historial de pagos", "fa-regular fa-eye", "confirmarEdicion", "confirmarAnulacion", "abrirVisorPDF", "EJECUTAR_ANULACION_SEGURA", ".v31-new-search:hover", ".v31-order-actions", "v31-doc-popover"]
missing_output = [m for m in required_output_markers if m not in source]
if missing_output: raise SystemExit("La vista conectada perdió marcadores: " + ", ".join(missing_output))
OUTPUT.write_text(source, encoding="utf-8")
print(f"Generated {OUTPUT.name}: {len(source)} bytes")
